class Solution {
    vector<pair<int, int>> canonical(const vector<pair<int, int>>& cells) {
        vector<pair<int, int>> best;
        for (int t = 0; t < 8; ++t) {
            vector<pair<int, int>> points;
            for (auto p : cells) {
                int x = p.first;
                int y = p.second;
                int a = (t & 1) ? -x : x;
                int b = (t & 2) ? -y : y;
                if (t & 4) {
                    swap(a, b);
                }
                points.push_back({a, b});
            }
            sort(points.begin(), points.end());
            int dx = points[0].first;
            int dy = points[0].second;
            for (auto& p : points) {
                p.first -= dx;
                p.second -= dy;
            }
            if (t == 0 || points < best) {
                best = points;
            }
        }
        return best;
    }

public:
    int numDistinctIslands2(vector<vector<int>>& grid) {
        int m = grid.size();
        if (m == 0) {
            return 0;
        }
        int n = grid[0].size();
        set<vector<pair<int, int>>> uniqueShapes;
        int dr[4] = {1, -1, 0, 0};
        int dc[4] = {0, 0, 1, -1};
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] != 1) {
                    continue;
                }
                queue<pair<int, int>> q;
                vector<pair<int, int>> cells;
                q.push({r, c});
                grid[r][c] = 0;
                while (!q.empty()) {
                    auto p = q.front();
                    q.pop();
                    cells.push_back(p);
                    for (int d = 0; d < 4; ++d) {
                        int nr = p.first + dr[d];
                        int nc = p.second + dc[d];
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n
                            && grid[nr][nc] == 1) {
                            grid[nr][nc] = 0;
                            q.push({nr, nc});
                        }
                    }
                }
                uniqueShapes.insert(canonical(cells));
            }
        }
        return uniqueShapes.size();
    }
};
